package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;
import java.util.function.Function;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.claim.LateCharge;
import net.officefloor.hq.app.claim.Rounding;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;

/**
 * The sheet's figures as the screen shows them: each person's claimed, due-total and overdue-total,
 * and the sheet's claimed-total, due-total and overdue-total. A change takes a {@link #snapshot} before it and passes it
 * to {@link #recordChanges} after its own audit lines, which then records a ROLLUP line for each
 * person whose figures moved (people in the order they were added; a person new to the sheet
 * counts as moved) and a TOTALS line when any of the sheet's totals moved.
 */
@Service
public class RollupService {

    /** A person's figures: claimed, due-total held to the sheet's cap (null: n/a), and
     *  overdue-total (the dues their overdue counting claims show, n/a ones skipped, not capped). */
    public record Figures(String name, BigDecimal claimed, BigDecimal dueTotal, BigDecimal overdueTotal) {
        boolean sameAs(Figures other) {
            return other != null && claimed.compareTo(other.claimed) == 0
                    && Objects.equals(text(dueTotal), text(other.dueTotal))
                    && overdueTotal.compareTo(other.overdueTotal) == 0;
        }
    }

    /** The sheet's figures at one moment: each person's, by person id in the order they were added. */
    public record Snapshot(Map<Long, Figures> people) {
        BigDecimal claimedTotal() {
            return people.values().stream().map(Figures::claimed).reduce(zero(), BigDecimal::add);
        }

        /** Everyone's due-total added up, skipping n/a. */
        BigDecimal dueTotal() {
            return people.values().stream().map(Figures::dueTotal).filter(Objects::nonNull)
                    .reduce(zero(), BigDecimal::add);
        }

        BigDecimal overdueTotal() {
            return people.values().stream().map(Figures::overdueTotal).reduce(zero(), BigDecimal::add);
        }
    }

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateRepository rates;
    private final SheetRepository sheets;
    private final Audit audit;

    public RollupService(PersonRepository people, ClaimRepository claims, RateRepository rates,
            SheetRepository sheets, Audit audit) {
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** The sheet's figures now, as the store (and this transaction) holds them. */
    public Snapshot snapshot(String sheetId) {
        Optional<Sheet> sheet = sheets.findById(sheetId);
        LocalDate today = sheet.map(Sheet::getToday).orElseGet(LocalDate::now);
        Function<LocalDate, BigDecimal> floor = floorOf(sheet);
        BigDecimal cap = sheet.map(Sheet::getCap).orElse(null);
        LateCharge late = LateCharge.of(sheet);
        List<Rate> sheetRates = rates.findBySheetIdOrderByGradeAsc(sheetId);
        List<Person> sheetPeople = people.findBySheetIdOrderByIdAsc(sheetId);
        Map<Long, Person> held = heldPeople(sheetPeople);
        List<Claim> sheetClaims = claims.findBySheetIdOrderByIdDesc(sheetId);
        Function<Claim, RoundingMode> rounding = roundingOf(sheet, sheetClaims);
        Map<Long, List<Claim>> counted = new LinkedHashMap<>();
        for (Claim c : sheetClaims) {
            if (counts(c, held, today)) {
                counted.computeIfAbsent(c.getPersonId(), id -> new ArrayList<>()).add(c);
            }
        }
        Map<Long, Figures> out = new LinkedHashMap<>();
        for (Person p : sheetPeople) {
            List<Claim> theirs = counted.getOrDefault(p.getId(), List.of());
            BigDecimal claimed = theirs.stream().map(Claim::getAmount).reduce(zero(), BigDecimal::add);
            BigDecimal overdue = theirs.stream()
                    .filter(c -> c.getStatus().isOpen() && c.getDueBy().isBefore(today))
                    .map(c -> shownDueOf(c, p, sheetRates, floor, late, rounding))
                    .filter(Objects::nonNull)
                    .reduce(zero(), BigDecimal::add);
            out.put(p.getId(), new Figures(p.getName(), claimed,
                    Sheet.capped(dueTotalOf(theirs, p, sheetRates, today, floor, late, rounding), cap), overdue));
        }
        return new Snapshot(out);
    }

    /** Each person's due-total for the period from {@code from} to {@code to}, inclusive, by person
     *  id, for everyone on the sheet: the dues (n/a ones skipped) their OPEN and SETTLED claims dated
     *  inside it show now (OPEN ones within a hold of their person, unbound, or deferred, left out). */
    public Map<Long, BigDecimal> dueByPersonBetween(String sheetId, LocalDate from, LocalDate to) {
        Optional<Sheet> sheet = sheets.findById(sheetId);
        LocalDate today = sheet.map(Sheet::getToday).orElseGet(LocalDate::now);
        Function<LocalDate, BigDecimal> floor = floorOf(sheet);
        LateCharge late = LateCharge.of(sheet);
        List<Rate> sheetRates = rates.findBySheetIdOrderByGradeAsc(sheetId);
        List<Person> sheetPeople = people.findBySheetIdOrderByIdAsc(sheetId);
        Map<Long, Person> held = heldPeople(sheetPeople);
        Map<Long, Person> byId = sheetPeople.stream().collect(Collectors.toMap(Person::getId, p -> p));
        List<Claim> sheetClaims = claims.findBySheetIdOrderByIdDesc(sheetId);
        Function<Claim, RoundingMode> rounding = roundingOf(sheet, sheetClaims);
        Map<Long, BigDecimal> out = new LinkedHashMap<>();
        for (Person p : sheetPeople) {
            out.put(p.getId(), zero());
        }
        sheetClaims.stream()
                .filter(c -> counts(c, held, today))
                .filter(c -> !c.getDate().isBefore(from) && !c.getDate().isAfter(to))
                .filter(c -> byId.containsKey(c.getPersonId()))
                .forEach(c -> {
                    BigDecimal due = shownDueOf(c, byId.get(c.getPersonId()), sheetRates, floor, late, rounding);
                    if (due != null) {
                        out.merge(c.getPersonId(), due, BigDecimal::add);
                    }
                });
        return out;
    }

    /** Record, once the transaction commits, a ROLLUP line for each person whose figures moved
     *  since {@code before}, then a TOTALS line when the sheet's totals moved. */
    public void recordChanges(String sheetId, String user, Snapshot before) {
        Snapshot after = snapshot(sheetId);
        after.people().forEach((id, now) -> {
            if (!now.sameAs(before.people().get(id))) {
                audit.recordOnCommit("ROLLUP sheet=" + sheetId + " by=" + user + " person=" + now.name()
                        + " claimed=" + text(now.claimed()) + " due-total=" + text(now.dueTotal()) + " overdue-total=" + text(now.overdueTotal()));
            }
        });
        if (after.claimedTotal().compareTo(before.claimedTotal()) != 0
                || after.dueTotal().compareTo(before.dueTotal()) != 0
                || after.overdueTotal().compareTo(before.overdueTotal()) != 0) {
            audit.recordOnCommit("TOTALS sheet=" + sheetId + " by=" + user + " claimed-total="
                    + text(after.claimedTotal()) + " due-total=" + text(after.dueTotal())
                    + " overdue-total=" + text(after.overdueTotal()));
        }
    }

    /** Whether a claim counts toward claimed and due totals: only OPEN (or PENDING) and SETTLED ones
     *  do, but not an open one dated within a hold of its person (by id in {@code held}) unless bound
     *  by a statement, nor one deferred on the sheet's today. */
    private static boolean counts(Claim c, Map<Long, Person> held, LocalDate today) {
        if (c.getStatus() == ClaimStatus.SETTLED) {
            return true;
        }
        if (!c.getStatus().isOpen() || c.isDeferredOn(today)) {
            return false;
        }
        Person person = held.get(c.getPersonId());
        return c.isBound() || person == null || !person.heldOn(c.getDate());
    }

    private static Map<Long, Person> heldPeople(List<Person> sheetPeople) {
        return sheetPeople.stream().filter(Person::isHeld).collect(Collectors.toMap(Person::getId, p -> p));
    }

    /** A person's due-total: the sum of the dues their counting claims show (n/a ones skipped);
     *  null (n/a) when their grade in force on the sheet's today has no rate then, unless a claim
     *  shows a due (a fixed or bound one, or one at the rate of the grade they had on its date). */
    private static BigDecimal dueTotalOf(List<Claim> counted, Person person, List<Rate> sheetRates, LocalDate today,
            Function<LocalDate, BigDecimal> floor, LateCharge late, Function<Claim, RoundingMode> rounding) {
        List<BigDecimal> dues = counted.stream()
                .map(c -> shownDueOf(c, person, sheetRates, floor, late, rounding))
                .filter(Objects::nonNull)
                .toList();
        if (inForce(person, sheetRates, today).isEmpty() && dues.isEmpty()) {
            return null;
        }
        return dues.stream().reduce(zero(), BigDecimal::add);
    }

    /** The due a claim shows: the due fixed when it was settled, else the one a statement bound it
     *  to (null: n/a), else its amount times the rate in force on its date of its person's grade
     *  then, rounded as its rounding policy has it,
     *  raised to the sheet's floor in force on its date (a correction's never is); an unsettled one with its late charge on top. */
    private static BigDecimal shownDueOf(Claim c, Person person, List<Rate> sheetRates, Function<LocalDate, BigDecimal> floor,
            LateCharge late, Function<Claim, RoundingMode> rounding) {
        if (c.getSettledDue() != null) {
            return c.getSettledDue();
        }
        RoundingMode mode = rounding.apply(c);
        return late.addTo(c, figureOf(c, person, sheetRates, floor, mode), mode);
    }

    /** A claim's figure before any late charge: the one a statement bound it to (null: n/a), else
     *  its live due. */
    private static BigDecimal figureOf(Claim c, Person person, List<Rate> sheetRates, Function<LocalDate, BigDecimal> floor,
            RoundingMode mode) {
        if (c.isBound()) {
            return c.getStatedDue();
        }
        return inForce(person, sheetRates, c.getDate())
                .map(r -> c.getAmount().multiply(r.getPct()).divide(BigDecimal.valueOf(100), 2, mode))
                .map(due -> c.isCorrection() ? due : due.max(floor.apply(c.getDate())))
                .orElse(null);
    }

    /** How each claim's live figures round: by the sheet's policy date against its date, or for a
     *  correction the date of the claim (of the same person) it corrects. */
    private static Function<Claim, RoundingMode> roundingOf(Optional<Sheet> sheet, List<Claim> sheetClaims) {
        Rounding rounding = Rounding.of(sheet);
        Map<String, LocalDate> numbered = new LinkedHashMap<>();
        for (Claim c : sheetClaims) {
            if (c.getNumber() != null) {
                numbered.putIfAbsent(c.getPersonId() + "/" + c.getNumber(), c.getDate());
            }
        }
        return c -> rounding.on(c.getCorrects() == null ? c.getDate()
                : numbered.getOrDefault(c.getPersonId() + "/" + c.getCorrects(), c.getDate()));
    }

    /** The rate in force on a date for the person's grade in force then; none when that one's
     *  to-date has passed by then. */
    private static Optional<Rate> inForce(Person person, List<Rate> sheetRates, LocalDate on) {
        String grade = person.gradeOn(on);
        return sheetRates.stream()
                .filter(r -> r.getGrade().equals(grade) && r.appliesOn(on))
                .max(Comparator.comparing(Rate::getFrom, Comparator.nullsFirst(Comparator.naturalOrder())))
                .filter(r -> r.runsThrough(on));
    }

    /** The sheet's floor in force on each date. */
    private static Function<LocalDate, BigDecimal> floorOf(Optional<Sheet> sheet) {
        return on -> sheet.map(s -> s.floorOn(on)).orElse(Sheet.DEFAULT_FLOOR);
    }

    private static BigDecimal zero() {
        return BigDecimal.ZERO.setScale(2);
    }

    /** A figure as the screen shows it: two decimals, or n/a. */
    private static String text(BigDecimal value) {
        return value == null ? "n/a" : value.setScale(2).toPlainString();
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.orm.ObjectOptimisticLockingFailureException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class PersonService {

    private final PersonRepository people;
    private final PersonStatementRepository statements;
    private final PersonPatronRepository patrons;
    private final SheetService sheets;
    private final RollupService rollup;
    private final Audit audit;

    public PersonService(PersonRepository people, PersonStatementRepository statements,
            PersonPatronRepository patrons, SheetService sheets, RollupService rollup, Audit audit) {
        this.people = people;
        this.statements = statements;
        this.patrons = patrons;
        this.sheets = sheets;
        this.rollup = rollup;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public List<Person> list(String sheetId) {
        return people.findBySheetIdOrderByIdAsc(sheetId);
    }

    /** The sheet's today: the date the grade a person shows is in force on. */
    @Transactional(readOnly = true)
    public LocalDate today(String sheetId) {
        return sheets.today(sheetId);
    }

    @Transactional(readOnly = true)
    public Person get(String sheetId, long id) {
        return people.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
    }

    /** Each person's statement summary, by person id; a person with none is missing. */
    @Transactional(readOnly = true)
    public Map<Long, StatementSummary> statementSummaries(String sheetId) {
        return statements.findBySheetIdOrderByIdAsc(sheetId).stream()
                .collect(Collectors.groupingBy(PersonStatement::getPersonId,
                        Collectors.collectingAndThen(Collectors.toList(), StatementSummary::of)));
    }

    @Transactional(readOnly = true)
    public StatementSummary statementSummary(long personId) {
        return StatementSummary.of(statements.findByPersonIdOrderByIdAsc(personId));
    }

    /** Each person's patron ids in the order they were named, by person id; a person with none is missing. */
    @Transactional(readOnly = true)
    public Map<Long, List<Long>> patronIds(String sheetId) {
        return patrons.findBySheetIdOrderByIdAsc(sheetId).stream()
                .collect(Collectors.groupingBy(PersonPatron::getPersonId,
                        Collectors.mapping(PersonPatron::getPatronId, Collectors.toList())));
    }

    @Transactional(readOnly = true)
    public List<Long> patronIds(long personId) {
        return patrons.findByPersonIdOrderByIdAsc(personId).stream().map(PersonPatron::getPatronId).toList();
    }

    /** Name another person on the sheet as the person's patron; refused for the person themselves
     *  and for a patron they already have. */
    @Transactional
    public Person addPatron(String sheetId, String user, long id, long patronId) {
        Person person = people.findForUpdate(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        Person patron = people.findByIdAndSheetId(patronId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such patron"));
        if (person.getId().equals(patron.getId())) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "A person cannot be their own patron");
        }
        if (patrons.existsByPersonIdAndPatronId(person.getId(), patron.getId())) {
            throw patronAlready();
        }
        try {
            patrons.saveAndFlush(new PersonPatron(sheetId, person.getId(), patron.getId()));
        } catch (DataIntegrityViolationException e) {
            throw patronAlready(); // named by another user at the same moment
        }
        audit.recordOnCommit("PATRON_ADDED sheet=" + sheetId + " by=" + user
                + " name=" + person.getName() + " patron=" + patron.getName());
        return person;
    }

    /** Add a person to the sheet (the sheet is created first if it was never loaded). */
    @Transactional
    public Person add(String sheetId, String user, String name, String grade) {
        sheets.load(sheetId, user);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        String trimmed = name.trim();
        requireUnusedName(sheetId, null, trimmed);
        Person person;
        try {
            person = people.saveAndFlush(new Person(sheetId, trimmed, grade));
        } catch (DataIntegrityViolationException e) {
            throw nameInUse(); // added by another user at the same moment
        }
        record("PERSON_ADDED", sheetId, user, person, sheets.today(sheetId));
        rollup.recordChanges(sheetId, user, before);
        return person;
    }

    /** Save a person; refused when {@code version} (the one the editor loaded) is no longer the stored one.
     *  The grade is recorded from {@code gradeFrom} (null: the sheet's today), keeping those already
     *  recorded; with no from-date, a grade the same as the one in force on the sheet's today records nothing. */
    @Transactional
    public Person update(String sheetId, String user, long id, Long version, String name, String grade,
            LocalDate gradeFrom) {
        Person person = people.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        if (version == null || version != person.getVersion()) {
            throw savedByAnother();
        }
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        String trimmed = name.trim();
        requireUnusedName(sheetId, id, trimmed);
        person.setName(trimmed);
        LocalDate today = sheets.today(sheetId);
        if (gradeFrom != null || !grade.equals(person.gradeOn(today))) {
            person.recordGrade(grade, gradeFrom != null ? gradeFrom : today);
        }
        try {
            people.flush();
        } catch (DataIntegrityViolationException e) {
            throw nameInUse(); // taken by another user at the same moment
        } catch (ObjectOptimisticLockingFailureException e) {
            throw savedByAnother(); // saved by another user at the same moment
        }
        record("PERSON_EDITED", sheetId, user, person, today);
        rollup.recordChanges(sheetId, user, before);
        return person;
    }

    /** Retire a person from a date (a missing one takes the sheet's today); they count as retired
     *  at once. Retiring them again moves the date. */
    @Transactional
    public Person retire(String sheetId, String user, long id, LocalDate from) {
        Person person = people.findForUpdate(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        LocalDate on = from != null ? from : sheets.today(sheetId);
        person.setRetiredFrom(on);
        people.flush();
        audit.recordOnCommit("PERSON_RETIRED sheet=" + sheetId + " by=" + user
                + " name=" + person.getName() + " from=" + on);
        return person;
    }

    /** Add a hold to a person from a date (a missing one takes the sheet's today) to an optional
     *  one; their OPEN claims dated within it then count in no live total, unless bound by a
     *  statement. A to-date before the from-date is refused (422). */
    @Transactional
    public Person hold(String sheetId, String user, long id, LocalDate from, LocalDate to) {
        Person person = people.findForUpdate(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        LocalDate on = from != null ? from : sheets.today(sheetId);
        if (to != null && to.isBefore(on)) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "The to-date is before the from-date");
        }
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        person.addHold(on, to);
        people.flush();
        audit.recordOnCommit("PERSON_HELD sheet=" + sheetId + " by=" + user
                + " name=" + person.getName() + " from=" + on);
        rollup.recordChanges(sheetId, user, before);
        return person;
    }

    /** Written with the grade in force on {@code today}, the sheet's today. */
    private void record(String event, String sheetId, String user, Person person, LocalDate today) {
        audit.recordOnCommit(event + " sheet=" + sheetId + " by=" + user
                + " name=" + person.getName() + " grade=" + person.gradeOn(today));
    }

    /** Refuse a name another person on the sheet already has (ignoring case). */
    private void requireUnusedName(String sheetId, Long exceptId, String name) {
        boolean taken = people.findBySheetIdAndNameIgnoreCase(sheetId, name).stream()
                .anyMatch(p -> !p.getId().equals(exceptId));
        if (taken) {
            throw nameInUse();
        }
    }

    private static ResponseStatusException savedByAnother() {
        return new ResponseStatusException(HttpStatus.PRECONDITION_FAILED, "Saved by someone else since it was loaded");
    }

    private static ResponseStatusException patronAlready() {
        return new ResponseStatusException(HttpStatus.CONFLICT, "Already a patron");
    }

    private static ResponseStatusException nameInUse() {
        return new ResponseStatusException(HttpStatus.CONFLICT, "Name already in use");
    }
}
