387	    /** Take a statement of a person: record their due-total now, and bind each of their claims
388	     *  that counts (OPEN, PENDING or SETTLED, but no unbound open one within a hold, nor a deferred one) to its figure now; the others
389	     *  are left unbound. */
390	    @Transactional
391	    public Statement statement(String sheetId, String user, long personId) {
392	        Person person = people.findForUpdate(personId, sheetId)
393	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
394	        LocalDate today = sheets.today(sheetId);
395	        List<Claim> theirs = claims.findByPersonForUpdate(personId, sheetId);
396	        RollupService.Snapshot before = rollup.snapshot(sheetId);
397	        List<Claim> counted = theirs.stream().filter(c -> counts(c, person, today)).toList();
398	        BigDecimal dueTotal = Sheet.capped(dueTotalOf(counted, person, today), sheets.cap(sheetId));
399	        for (Claim c : theirs) {
400	            if (counts(c, person, today)) {
401	                // the statement binds the figure; the late charge keeps following the sheet's today
402	                c.bind(c.getSettledDue() != null ? c.getSettledDue() : figureOf(c, person));
403	            } else {
404	                c.unbind();
405	            }
406	        }
407	        claims.flush();
408	        statements.saveAndFlush(new PersonStatement(sheetId, personId, dueTotal, counted.size(), today, user));
409	        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
410	                + " due-total=" + (dueTotal == null ? "n/a" : dueTotal.toPlainString()) + " claims=" + counted.size());
411	        rollup.recordChanges(sheetId, user, before);
412	        return new Statement(person, StatementSummary.of(statements.findByPersonIdOrderByIdAsc(personId)), theirs);
413	    }
