415	    /** The number a claim dated {@code date} takes as it is opened: under period numbering (set,
416	     *  and the sheet's today on or after it) the next within the period containing the date
417	     *  (<period name>-<n>), or X-<n> when none does; otherwise the sheet's next number. */
418	    private String nextNumber(String sheetId, LocalDate date) {
419	        if (!sheets.periodNumberingOn(sheetId)) {
420	            return String.valueOf(sheets.nextClaimNumber(sheetId));
421	        }
422	        // held until the transaction ends, so two claims opened at once are numbered one after the other
423	        sheets.lock(sheetId);
424	        String prefix = periods.containing(sheetId, date).map(Period::getName).orElse(NO_PERIOD) + "-";
425	        int last = claims.findNumbers(sheetId).stream()
426	                .filter(n -> n.startsWith(prefix))
427	                .map(n -> n.substring(prefix.length()))
428	                .filter(n -> n.matches("\\d{1,9}"))
429	                .mapToInt(Integer::parseInt)
430	                .max().orElse(0);
431	        return prefix + (last + 1);
432	    }
433	
434	    /** Refuse (423) a change to a claim dated in a closed period, holding the sheet locked until
435	     *  the transaction ends so a period cannot be closed meanwhile. */
436	    private void refuseIfClosed(String sheetId, LocalDate date) {
437	        sheets.lock(sheetId);
438	        periods.refuseIfClosed(sheetId, date);
439	    }
440	
441	    /** The number a claim of the amount corrects: none unless the amount is negative, when it must
442	     *  be the number of a SETTLED claim of the same person, or the claim is refused (422). */
443	    private String correctedBy(String sheetId, long personId, BigDecimal amount, String corrects) {
444	        if (amount.signum() >= 0) {
445	            return null;
446	        }
447	        if (corrects == null
448	                || !claims.existsBySheetIdAndPersonIdAndNumberAndStatus(sheetId, personId, corrects, ClaimStatus.SETTLED)) {
449	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
450	                    "A negative amount must correct a settled claim of the same person");
451	        }
452	        return corrects;
453	    }
454	
455	    /** Refuse (422) a claim dated after its person's retirement date. */
456	    private static void refuseIfRetired(Person person, LocalDate date) {
457	        if (person.retiredBefore(date)) {
458	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
459	                    "The date is after the person's retirement date");
460	        }
461	    }
462	
463	    /** Whether a claim counts toward claimed and due totals: only OPEN (or PENDING) and SETTLED ones
464	     *  do, but not an open one dated within a hold of its person unless bound by a statement, nor
465	     *  one deferred on the sheet's today. */
466	    private static boolean counts(Claim c, Person person, LocalDate today) {
467	        return c.getStatus() == ClaimStatus.SETTLED
468	                || (c.getStatus().isOpen() && !c.isDeferredOn(today) && (c.isBound() || !person.heldOn(c.getDate())));
469	    }
470	
471	    /** The due a claim shows: the due fixed when it was settled, else its figure with its late
472	     *  charge on top. */
473	    private BigDecimal shownDueOf(Claim claim, Person person) {
474	        if (claim.getSettledDue() != null) {
475	            return claim.getSettledDue();
476	        }
477	        return LateCharge.of(sheets.find(claim.getSheetId())).addTo(claim, figureOf(claim, person), roundingOf(claim));
478	    }
479	
480	    /** A claim's figure before any late charge: the one a statement bound it to (null: n/a), else
481	     *  (unbound, or PENDING) its live due. */
482	    private BigDecimal figureOf(Claim claim, Person person) {
483	        return claim.isBound() ? claim.getStatedDue() : dueOf(claim, person);
484	    }
485	
486	    /** A person's due-total: the sum of the dues their counting claims show (n/a ones skipped);
487	     *  null (n/a) when their grade in force on the sheet's today has no rate then, unless a claim
488	     *  shows a due (a fixed or bound one, or one at the rate of the grade they had on its date). */
489	    private BigDecimal dueTotalOf(List<Claim> counted, Person person, LocalDate today) {
490	        List<BigDecimal> dues = counted.stream().map(c -> shownDueOf(c, person)).filter(d -> d != null).toList();
491	        if (rates.findInForce(person.getSheetId(), person.gradeOn(today), today).isEmpty() && dues.isEmpty()) {
492	            return null;
493	        }
494	        return dues.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
495	    }
496	
497	    /** The claim's amount times the rate, in force on the claim's date, of its person's grade then, divided by
498	     *  100, rounded as its rounding policy has it, raised to the sheet's floor in force on its date (a correction's never is); null with no rate in force then. */
499	    private BigDecimal dueOf(Claim claim, Person person) {
500	        BigDecimal floor = sheets.floorOn(claim.getSheetId(), claim.getDate());
501	        return rates.findInForce(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate())
502	                .map(Rate::getPct)
503	                .map(pct -> claim.getAmount().multiply(pct).divide(BigDecimal.valueOf(100), 2, roundingOf(claim)))
504	                .map(due -> claim.isCorrection() ? due : due.max(floor))
505	                .orElse(null);
506	    }
507	
508	    /** How the claim's live figures round: by the sheet's policy date against its date, or for a
509	     *  correction the date of the claim it corrects. */
510	    private RoundingMode roundingOf(Claim claim) {
511	        LocalDate on = claim.getCorrects() == null ? claim.getDate()
512	                : claims.findFirstBySheetIdAndPersonIdAndNumber(claim.getSheetId(), claim.getPersonId(), claim.getCorrects())
513	                        .map(Claim::getDate).orElse(claim.getDate());
514	        return Rounding.of(sheets.find(claim.getSheetId())).on(on);
515	    }
516	
517	    private void record(String event, String user, Person person, Claim claim) {
518	        record(event, user, person, claim, claim.getNumber());
519	    }
520	
521	    /** Amounts are written as the screen shows them (two decimals), dates as yyyy-mm-dd. */
522	    private void record(String event, String user, Person person, Claim claim, String number) {
523	        record(event, user, person, claim, number, "");
524	    }
525	
526	    private void record(String event, String user, Person person, Claim claim, String number, String extra) {
527	        audit.recordOnCommit(event + " sheet=" + claim.getSheetId() + " by=" + user
528	                + " person=" + person.getName() + " amount=" + claim.getAmount().setScale(2).toPlainString()
529	                + " date=" + claim.getDate() + (number != null ? " number=" + number : "") + extra);
530	    }
531	
532	    private static String noteOf(String note) {
533	        return note == null ? "" : note.trim();
534	    }
535	}
